fn get_column(input: &Vec<Vec<i8>>, j: usize, m: usize, n: usize) -> Vec<i8> {
    // j should be less than m (valid column index)
    // n is number of rows, m is number of columns
    let mut col = Vec::with_capacity(n);
    
    for i in 0..n {
        // Access element at row i, column j
        col.push(input[i][j]);
    }
    
    col
}

fn column_stack(input: Vec<Vec<i8>>, m: usize, n: usize) -> Vec<Vec<i8>> {
    // Create result vector with m rows (transposed)
    let mut result = Vec::with_capacity(m);
    
    // For each column j in the original matrix
    for j in 0..m {
        // Get the j-th column as a vector
        let column = get_column(&input, j, m, n);
        // Add this column as a row in the result
        result.push(column);
    }
    
    result
}